/** The mark's gradient. One definition per document would be ideal, but two
 *  marks on a page is not a thing that happens, and a unique id per instance
 *  avoids the bug where a second copy borrows the first one's gradient and
 *  then loses it when the first unmounts. */
let gradSeq = 0;

export function MarkSvg({ height, style }: { height: number; style?: React.CSSProperties }) {
  const id = "wg" + (gradSeq++);
  const w = Math.round((height * MARK.w) / MARK.h);
  const h = Math.round(height);
  return (
    <svg
      width={w} height={h} viewBox={`0 0 ${MARK.w} ${MARK.h}`}
      role="img" aria-label="Wasla"
      style={{ display: "block", width: w, height: h, ...style }}
    >
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stopColor="#fd193d" />
      <stop offset="6.25%" stopColor="#fd1745" />
      <stop offset="12.5%" stopColor="#fd1452" />
      <stop offset="18.75%" stopColor="#fd0e67" />
      <stop offset="25%" stopColor="#fd0c71" />
      <stop offset="31.25%" stopColor="#fb088b" />
      <stop offset="37.5%" stopColor="#f508a4" />
      <stop offset="43.75%" stopColor="#ec08bc" />
      <stop offset="50%" stopColor="#dd0bd9" />
      <stop offset="56.25%" stopColor="#c417ec" />
      <stop offset="62.5%" stopColor="#a541d1" />
      <stop offset="68.75%" stopColor="#7b799b" />
      <stop offset="75%" stopColor="#68a17d" />
      <stop offset="81.25%" stopColor="#59bf66" />
      <stop offset="87.5%" stopColor="#53d854" />
      <stop offset="93.75%" stopColor="#54e44e" />
      <stop offset="100%" stopColor="#57e650" />
        </linearGradient>
      </defs>
      <g transform={MARK.t} fill={`url(#${id})`} fillRule="evenodd">
        <path d={MARK.d} />
      </g>
    </svg>
  );
}

/** Lettering: the wordmark and the tagline, in either language. */
function Letters({ p, height, label, style }: { p: Piece; height: number; label?: string; style?: React.CSSProperties }) {
  const w = Math.round((height * p.w) / p.h);
  const h = Math.round(height);
  return (
    <svg
      width={w} height={h} viewBox={`0 0 ${p.w} ${p.h}`}
      role={label ? "img" : undefined} aria-label={label} aria-hidden={label ? undefined : true}
      style={{ display: "block", width: w, height: h, maxWidth: "100%", ...style }}
    >
      <g transform={p.t} fill="currentColor" fillRule="evenodd">
        <path d={p.d} />
      </g>
    </svg>
  );
}

export const WordmarkSvg = ({ lang, height, style }: { lang: "en" | "ar"; height: number; style?: React.CSSProperties }) => (
  <Letters p={lang === "ar" ? WORD_AR : WORD_EN} height={height} label="Wasla" style={style} />
);

export const TaglineSvg = ({ lang, height, style }: { lang: "en" | "ar"; height: number; style?: React.CSSProperties }) => (
  <Letters p={lang === "ar" ? TAG_AR : TAG_EN} height={height} style={style} />
);

/** Aspect ratios, for anyone needing to reserve a box. */
export const MARK_RATIO = MARK.w / MARK.h;
